mapper.select:
SELECT answer_id, attempt_id, question_id, position_no, selected_option, score_awarded, answered_at
FROM exam_answer
WHERE attempt_id = #{attemptId} AND question_id = #{questionId}

mapper.update:
UPDATE exam_answer
SET selected_option = #{selectedOption}, score_awarded = #{scoreAwarded}, answered_at = NOW()
WHERE attempt_id = #{attemptId} AND question_id = #{questionId}
